class WheelGame extends GameEngine{constructor(n,t,e){super(n,"wheel",t),this.prizes=e,this.segments=t.segments||[],this.isSpinning=!1,this.currentRotation=0,this.state={spins:0}}render(n){const t=document.getElementById(n),e=`\n      <div class="game-container">\n        <div class="game-header">\n          <h1>🎡 Vòng Quay May Mắn</h1>\n          <p>Quay để nhận thưởng</p>\n          <div class="game-info">\n            <div class="info-badge">\n              💨 <strong>Tốc độ: ${this.config.speed}</strong>\n            </div>\n            <div class="info-badge">\n              🎯 <strong id="spinCount">0</strong> lần quay\n            </div>\n          </div>\n        </div>\n\n        <div class="wheel-container">\n          <div class="wheel-pointer"></div>\n          <div class="wheel-wrapper">\n            <div class="wheel" id="wheel">\n              ${this.renderSegments()}\n            </div>\n            <div class="wheel-center" id="wheelCenter">\n              🎁\n            </div>\n          </div>\n        </div>\n\n        <button class="spin-button" id="spinBtn" onclick="wheelGame.spin()">\n          🎯 QUAY NGAY\n        </button>\n      </div>\n    `;t.innerHTML=e,this.attachEventListeners()}renderSegments(){const n=360/this.segments.length;return this.segments.map((t,e)=>{const s=e*n,i=360/this.segments.length-90;return`\n        <div class="wheel-segment" \n             style="\n               background: linear-gradient(135deg, ${t.color} 0%, ${this.lightenColor(t.color)} 100%);\n               transform: rotate(${s}deg) skew(0deg, ${i}deg);\n               clip-path: polygon(50% 50%, 50% 0%, 100% 0%);\n             "\n             data-index="${e}">\n          <span style="\n            position: absolute;\n            left: 30%;\n            top: 50%;\n            transform: translateY(-50%) rotate(${-s-i}deg);\n            writing-mode: horizontal-tb;\n            font-size: 0.8rem;\n            font-weight: bold;\n            color: white;\n            text-shadow: 1px 1px 2px rgba(0,0,0,0.5);\n          ">${t.label.substring(0,8)}</span>\n        </div>\n      `}).join("")}lightenColor(n){const t=parseInt(n.replace("#",""),16);return("string"==typeof n&&"#"===n[0]?"#":"")+(16777216+65536*Math.min(255,30+(t>>16))+256*Math.min(255,30+(t>>8&255))+Math.min(255,30+(255&t))).toString(16).slice(1)}attachEventListeners(){document.getElementById("spinBtn").disabled=!1}async spin(){if(this.isSpinning||!this.isPlaying)return;this.isSpinning=!0,document.getElementById("spinBtn").disabled=!0,document.getElementById("spinBtn").textContent="⏳ ĐANG QUAY...";const n=Math.floor(Math.random()*this.segments.length),t=this.prizes[n],e=360-n*(360/this.segments.length)+1080,s=document.getElementById("wheel"),i=this.currentRotation,o=this.config.spin_time_ms||3e3,a=Date.now(),r=()=>{const l=Date.now()-a,c=Math.min(l/o,1),d=1-Math.pow(1-c,3);s.style.transform=`rotate(${i+e*d}deg)`,c<1?requestAnimationFrame(r):(this.currentRotation=e%360,this.onSpinComplete(n,t))};r(),this.state.spins++,document.getElementById("spinCount").textContent=this.state.spins}async onSpinComplete(n,t){this.isSpinning=!1,this.playSound("win"),await new Promise(n=>setTimeout(n,500)),await this.endGame(n),this.showResultScreen(t)}playSound(n){const t=new(window.AudioContext||window.webkitAudioContext),e=t.createOscillator(),s=t.createGain();e.connect(s),s.connect(t.destination),"win"===n&&(e.frequency.value=1200,s.gain.setValueAtTime(.2,t.currentTime),s.gain.exponentialRampToValueAtTime(.01,t.currentTime+.5),e.start(t.currentTime),e.stop(t.currentTime+.5))}showResultScreen(n){const t=`\n      <div class="result-screen">\n        <div class="result-emoji" style="color: ${n.color}">🎉</div>\n        <h2 class="result-title">Chúc Mừng!</h2>\n        <p class="result-message">Bạn đã quay trúng giải thưởng</p>\n        \n        <div class="result-detail">\n          <div style="font-size: 2rem; margin-bottom: 10px;">${n.icon||"🎁"}</div>\n          <strong style="color: ${n.color}; font-size: 1.3rem;">${n.name}</strong>\n          ${n.cash_amount?`<p>💰 ${n.cash_amount.toLocaleString()}đ</p>`:""}\n          <p style="font-size: 0.9rem; opacity: 0.8;">Rarity: <strong>${n.rarity}</strong></p>\n        </div>\n\n        <div class="result-buttons">\n          <button class="btn btn-primary" onclick="location.href='/thank-you'">\n            Nhận Thưởng\n          </button>\n          <button class="btn btn-secondary" onclick="wheelGame.shareResult()">\n            Chia Sẻ 📤\n          </button>\n        </div>\n      </div>\n    `;document.querySelector(".game-container").innerHTML=t}}